package com.axelsarassamit.ridedeck.dash;
import java.io.*;import java.nio.file.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class ClipDeletionTest {
 @Test public void selectedProtectedVideoAndMarkersOnly()throws Exception{File root=Files.createTempDirectory("dash-delete").toFile();try{File video=new File(root,"rear-0001.mp4"),ready=new File(video+".ready"),keep=new File(video+".protected"),other=new File(root,"front-0001.mp4"),csv=new File(root,"route.csv");for(File f:Arrays.asList(video,ready,keep,other,csv))assertTrue(f.createNewFile());ClipDeletion.Result result=ClipDeletion.delete(root,Arrays.asList(video,video));assertEquals(1,result.removed.size());assertEquals(0,result.failed);assertFalse(video.exists());assertFalse(ready.exists());assertFalse(keep.exists());assertTrue(other.exists());assertTrue(csv.exists());}finally{for(File f:root.listFiles())f.delete();root.delete();}}
 @Test public void outsideRootAndNonVideosStayUntouched()throws Exception{File root=Files.createTempDirectory("dash-root").toFile(),outside=File.createTempFile("dash-outside",".mp4");try{File csv=new File(root,"route.csv");assertTrue(csv.createNewFile());ClipDeletion.Result result=ClipDeletion.delete(root,Arrays.asList(outside,csv));assertEquals(2,result.failed);assertTrue(outside.exists());assertTrue(csv.exists());}finally{outside.delete();for(File f:root.listFiles())f.delete();root.delete();}}
}
